            payload: Dict[str, Any] = {'type': type, 'variantIndex': variantIndex}
            if value is not None:
                payload['value'] = user_message
            if data is not None and IS_DEBUG_ENABLED:
                payload['data'] = data
            if eventId is not None:
                payload['eventId'] = eventId

            await self.websocket.send_json(payload)
        except Exception as e:
            logger.exception('Failed to send WebSocket message')

    async def throw_error(self, message: str, log_details: str | None = None) -> None:
        # Internal detailed logging
        if log_details:
            logger.error(f'Generation failed: {log_details}')

        # User-facing error (generic unless debug mode)
        user_message = message if IS_DEBUG_ENABLED else 'An error occurred during code generation'

