function validateUrl(url: string, expectedProtocol: string): string {
    try {
        const parsed = new URL(url);
        if (!parsed.protocol.startsWith(expectedProtocol)) {
            console.error(`Invalid protocol. Expected ${expectedProtocol}, got ${parsed.protocol}`);
            throw new Error('Invalid URL protocol');
        }
        // Whitelist allowed domains in production
