            const allowedDomains = [
                'api.screenshottocode.com',
                'api.example.com'
            ];
            if (!allowedDomains.includes(parsed.hostname)) {
                throw new Error(`Domain ${parsed.hostname} not in whitelist`);
            }
        }
        return url;
    } catch (error) {
        console.error('Invalid URL configuration:', error);
        // Fallback to safe default
        return expectedProtocol === 'ws' || expectedProtocol === 'wss' 
            ? 'ws://127.0.0.1:7001'
            : 'http://127.0.0.1:7001';
